def until(fn,why,timeout=25):
    end=time.monotonic()+timeout
    while time.monotonic()<end:
        try:
            v=fn()
            if v:return v
        except Exception:pass
        time.sleep(.25)
    raise AssertionError(why)

def shot(w):
    img=w.capture_as_image().convert("RGB")
    img.thumbnail((972,720))
    b=io.BytesIO();img.save(b,format="JPEG",quality=82,optimize=True)
    return base64.b64encode(b.getvalue()).decode("ascii")

def matching(items):
    out={}
    for item in items:
        try:name=item.element_info.name or item.window_text()
        except Exception:continue
        for key,aliases in targets.items():
            if any(a==name or a in name for a in aliases):
                out[key]=(item,name);break
    return out

def materialized(rows):
    out={}
    for key,(item,name) in rows.items():
        try:
            r=item.rectangle()
            if item.is_visible() and r.width()>0 and r.height()>0:
                out[key]=(item,name,r)
        except Exception:pass
    return out

